/** The asset's corner radius as a fraction of its edge (48 / 400). */
export const BRAND_TILE_RADIUS_RATIO = 0.12;

/* The artwork is inset toward the lower right of its tile — it spans only
   x 93..392 of the 400 box, with the top-left corner empty. Inside the tile
   that inset IS the composition, but a standalone glyph drawn on the full box
   renders with lopsided padding and looks mis-centred next to text. These are
   the true bounds, measured by flattening the path's curves. */
export const WINGS_MARK_TRIM_VIEW_BOX = "92.99 59.92 299.39 332.46";

/** Width / height of the trimmed glyph. */
export const WINGS_MARK_TRIM_ASPECT = 299.39 / 332.46;

/**
 * Smallest height at which the monochrome glyph stays readable.
 *
 * The feather strokes are *negative* space in the path — inside `BrandTile`
 * they are the red field showing through, at full contrast. Filled positive in
 * a single colour they are gaps between thin fills instead, and below roughly
 * this size they close up: on device a 24pt `WingsMark` reads as a smudge with
 * hairline scratches rather than a logo. Reach for `BrandTile` at small sizes,
 * where the knockout does the work no monochrome fill can.
 */
export const WINGS_MARK_MIN_LEGIBLE_SIZE = 48;

export interface WingsMarkProps {
  /**
   * Height in pt. Trimmed, width follows WINGS_MARK_TRIM_ASPECT.
   * See WINGS_MARK_MIN_LEGIBLE_SIZE before going small.
   */
  size?: number;
  /** Defaults to the theme foreground so the glyph can be used monochrome. */
  color?: string;
  /**
   * Keep the tile's full 400 box, inset and all. Only wanted when aligning
   * against a `BrandTile` of the same size; standalone use wants the default.
   */
  untrimmed?: boolean;
}

/** The wings on their own, untiled — takes the active theme's foreground. */
export function WingsMark({ size = 88, color, untrimmed }: WingsMarkProps) {
  const colors = useThemeColors();
  return (
    <Svg
      width={untrimmed ? size : size * WINGS_MARK_TRIM_ASPECT}
      height={size}
      viewBox={untrimmed ? WINGS_MARK_VIEW_BOX : WINGS_MARK_TRIM_VIEW_BOX}
      fill="none"
    >
      <Path d={WINGS_MARK_PATH} fill={color ?? colors.fg} />
    </Svg>
  );
}

export interface BrandTileProps {
  /** Edge length in pt; the tile is square. */
  size?: number;
  /** Brand red by default — intentionally not theme-derived. */
  tileColor?: string;
  /** Stone 0 by default — intentionally not theme-derived. */
  markColor?: string;
  /** Corner radius in pt. Defaults to the asset ratio; pass 0 for square. */
  radius?: number;
}

/** The full red lockup: brand-red rounded tile with the wings knocked out. */
export function BrandTile({ size = 88, tileColor, markColor, radius }: BrandTileProps) {
  const corner = radius ?? size * BRAND_TILE_RADIUS_RATIO;
  return (
    <Svg width={size} height={size} viewBox={WINGS_MARK_VIEW_BOX} fill="none">
      <Rect
        width={400}
        height={400}
        rx={(corner / size) * 400}
        fill={tileColor ?? palette.brick[400]}
      />
      <Path d={WINGS_MARK_PATH} fill={markColor ?? palette.stone[0]} />
    </Svg>
  );
}
